insert into public.data_policies (id, status, sort_order, name, agency, region_scope, effective_year, application_start, application_end, benefit_type, benefit_summary, monthly_cap, max_months, lump_sum_cap, lump_sum_basis, required_inputs, exclusive_group, discovery_age_min, discovery_age_max, discovery_regions, discovery_statuses, discovery_income_bracket_min, discovery_income_bracket_max, discovery_housing_types, source_url, apply_url, youth_policy_no, gov24_service_id, notes, edit_note)
values ('moland-youth-rent-support', 'published', 10, '청년월세 지원 (2026년 상시사업 전환)', '국토교통부', '전국', 2026, '2026-03-30', '2026-05-29', 'rent_capped_monthly', '실제 납부 월세 범위 내 월 최대 20만원, 생애 1회 최대 24개월 (총 최대 480만원)', 200000, 24, null, null, '{"birthDate","livesApartFromParents","canRegisterResidence","hasNoHouse","isContractHolder","householdSize","useOriginHousehold","ownHouseholdMonthlyIncome","originHouseholdMonthlyIncome","receivingOtherRentSupport"}', '{"youth-rent-cash-support"}', 19, 34, '{"전국"}', '{"대학생","재직","구직"}', null, 3, '{"월세","연세"}', 'https://m.bokjiro.go.kr/ssis-tem/cms/mob/customer/notice/1309500_1155.html', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004661', '20260319005400112218', '161300000099', '복지로 공지 ''2026년 청년월세 지원 신청 안내'' 원문으로 확인(2026-08-23). 만 19~34세(1991~2007년생), 청년가구 중위소득 60% 이하 + 원가구 100% 이하, 월 20만원 × 최대 24회 생애 1회, 2026년 신규 6만명. 재학·재직·구직 제한은 공지에 없음. ⚠️ 2026년부터 상시사업으로 전환됐지만 접수 창구는 연중 열려 있지 않다 — 2026년 접수는 3/30 09시~5/29 16시로 이미 종료됐고, 선정자 발표는 9/14, 5월분 월세부터 소급 지급된다. 따라서 오늘 기준 판정은 ''신청 불가(접수 종료)''가 정상이다. 신규 수혜자는 2028년 12월까지만 지원. 재산기준(청년가구 1억 2,200만원 이하로 알려짐)은 공지 원문에서 확인되지 않아 코드에서 판정하지 않는다. 월세만 인정, 관리비는 지원 대상 금액에서 제외.', 'apps/web/data 에서 이관 (2026-11-02)');
insert into public.data_policies (id, status, sort_order, name, agency, region_scope, effective_year, application_start, application_end, benefit_type, benefit_summary, monthly_cap, max_months, lump_sum_cap, lump_sum_basis, required_inputs, exclusive_group, discovery_age_min, discovery_age_max, discovery_regions, discovery_statuses, discovery_income_bracket_min, discovery_income_bracket_max, discovery_housing_types, source_url, apply_url, youth_policy_no, gov24_service_id, notes, edit_note)
values ('iksan-youth-rent-support', 'published', 20, '익산형 청년월세 지원사업', '익산시', '전북특별자치도 익산시', 2026, '2026-04-15', '2026-09-30', 'rent_capped_monthly', '실제 납부 월세 범위 내 월 최대 20만원 × 최대 12개월 (총 최대 240만원), 선착순 250명 한정', 200000, 12, null, null, '{"birthDate","livesApartFromParents","hasNoHouse","householdSize","ownHouseholdMonthlyIncome","assetsUnder107M"}', '{"youth-rent-cash-support"}', 19, 34, '{"전북특별자치도 익산시"}', '{"대학생","재직","구직"}', 3, 5, '{"월세","연세"}', 'https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00005488', 'https://www.iksan.go.kr', '20260326005400212297', null, '2026년 회차 확인(2026-08-30). 신청기간 2026-04-15 ~ 2026-09-30, 모집 230명, 선착순 아님. 팀이 익산시에 직접 확인했다(2026-08-30). 온통청년 등록(plcyNo 20260326005400212297, 2026-03-26 등록 · 2026-06-05 갱신)과도 일치한다. ⚠️ 이전 값(2026-01-01~12-31, 선착순 250명)은 2024년 사업 기준 보도자료·뉴시스 기사에서 옮긴 추정치였다 — 실제 2026년 회차는 4월에 열려 9월에 닫힌다. 신선도 감지가 잡아낸 건이다. 요건도 2026년 공고(익산 청년숲)로 확인했다(2026-08-30): 19~34세 무주택, 임차보증금 5,000만원·월 임차료 60만원 이하 주택에 부모와 별도 거주, 청년가구 중위소득 130% 이하·재산 1억 700만원 이하, 행정복지센터 방문 신청(온라인 불가). ⚠️ **원가구 요건이 코드에 없다** — 공고는 원가구 중위소득 100% 이하·재산 3억 8,000만원 이하도 요구하는데 policy-rules.ts 의 iksan 규칙은 본인 가구만 본다. 부모 소득이 높아 탈락할 사람에게 ''예상 적용''이라고 말할 수 있다. requiredInputs 에 원가구 항목을 추가해야 하므로 2층 질문이 늘어난다 — 별도 판단이 필요하다. ⚠️ **소득 하한(60% 초과)은 공고에 없다** — 공고와 온통청년 모두 ''130% 이하''만 적는다. 아래 복지로 근거대로 ''국토부 사업 탈락자''라는 절차 요건을 소득 하한으로 근사한 값인데, 그 대가로 중위 60% 이하 청년에게 이 정책이 ''대상 아님''으로 표시된다. 유지 여부는 별도 판단이 필요하다. ⚠️ 복지로 지자체 복지서비스 페이지는 대상을 ''청년가구 소득초과로 정부형 청년월세 부적합 판정을 받은 자''로 적고 있다 — 소득 구간이 아니라 ''국토부 사업에 신청해서 소득 초과로 탈락했다''는 절차 요건이다. 소득 밴드(60~130%)는 그 상황을 근사한 값이므로, 실제로는 국토부 사업 신청·탈락 이력이 필요할 수 있다. 소득 하한이 있는 유일한 정책이라 discovery.incomeBracketMin(3) + incomeBracketMax(5)를 함께 쓴다 — 중위 60%(월 1,538,543원)와 130%(월 3,333,509원)가 각각 3번·5번 구간에 걸쳐 있다. 하한을 빼고 상한만 넣으면 저소득 청년 전원에게 ''가능성 있음''이 잘못 표시된다. ⚠️ 선착순이 아니므로 조기 마감 문구는 뺐다. 다만 230명 정원이 있어 정원 초과 시 선정에서 탈락할 수 있고, 그 현황은 앱에서 알 수 없다.', 'apps/web/data 에서 이관 (2026-11-02)');
insert into public.data_policies (id, status, sort_order, name, agency, region_scope, effective_year, application_start, application_end, benefit_type, benefit_summary, monthly_cap, max_months, lump_sum_cap, lump_sum_basis, required_inputs, exclusive_group, discovery_age_min, discovery_age_max, discovery_regions, discovery_statuses, discovery_income_bracket_min, discovery_income_bracket_max, discovery_housing_types, source_url, apply_url, youth_policy_no, gov24_service_id, notes, edit_note)
values ('jeonbuk-youth-settlement-support', 'published', 30, '전북청년 지역정착 지원사업', '전북특별자치도', '전북특별자치도', 2026, '2026-03-06', '2026-04-10', 'flat_monthly', '월 30만원 × 최대 12개월 (총 최대 360만원). 포인트 30% + 익산사랑상품권 70%로 지급 (전액 현금 아님)', 300000, 12, null, null, '{"birthDate","jeonbukResidentOverOneYear","employedInTargetSectorOver3Months","householdSize","ownHouseholdMonthlyIncome"}', '{}', 18, 39, '{"전북특별자치도"}', '{"재직"}', null, 5, null, 'https://youthforest.iksan.go.kr/board/view.iksan?boardId=BBS_0000015&menuCd=DOM_000000105002001000&dataSid=46029', 'https://ttd.ezwel.com/', '20250113005400210206', '654000000009', '익산청년시청 ''2026년 전북청년 지역정착 지원사업 모집공고(수정)''와 ''추가 모집공고'' 원문으로 확인(2026-08-23). 18~39세, 공고일 기준 1년 이상 거주, 농업·임업·어업·중소기업(정규직)·문화예술·연구소기업(정규직)에 3개월 이상 계속 종사, 가구 중위소득 150% 이하, 월 30만원 × 최대 12개월(포인트 30% + 익산사랑상품권 70%), 온라인 접수(ttd.ezwel.com), 문의 063-859-7384. ⚠️ 신청기간은 본모집 3/6~3/20 17시, 추가모집 3/30~4/10 17시로 두 차례였다 — 데이터 모델에 창구가 하나뿐이라 3/6~4/10 으로 합쳐 넣었고, 오늘 기준 판정은 ''신청 불가(접수 종료)''가 정상이다. discovery.statuses 를 ''재직''만 둔 이유: 대상 업종 정규직 3개월 이상 재직이 필수 요건이라 재학·구직 상태로는 대상이 되지 않는다(재학과 정규직을 병행하는 경우는 1층에서 ''해당 없음''으로 나오므로 2층 판정으로 확인해야 한다). 지급액의 70%가 현금이 아닌 지역화폐이므로 결과 화면에 반드시 표시할 것. 다른 월세지원과의 중복 수급 가능 여부는 공고에 명시되어 있지 않아 현재는 중복 허용으로 가정한다.', 'apps/web/data 에서 이관 (2026-11-02)');
insert into public.data_policies (id, status, sort_order, name, agency, region_scope, effective_year, application_start, application_end, benefit_type, benefit_summary, monthly_cap, max_months, lump_sum_cap, lump_sum_basis, required_inputs, exclusive_group, discovery_age_min, discovery_age_max, discovery_regions, discovery_statuses, discovery_income_bracket_min, discovery_income_bracket_max, discovery_housing_types, source_url, apply_url, youth_policy_no, gov24_service_id, notes, edit_note)
values ('iksan-newcomer-moving-cost-support', 'published', 40, '익산시 전입 청년 이사비·중개보수 지원사업', '익산시', '전북특별자치도 익산시', 2026, '2025-10-13', null, 'lump_sum', '이사비(최대 30만원) + 부동산 중개보수(최대 20만원) 실비를 1인당 최대 50만원까지 생애 1회 지원', null, null, 500000, 'oneTimeMoveCost', '{"birthDate"}', '{}', 18, 39, '{"전북특별자치도 익산시"}', '{"대학생","재직","구직"}', null, 5, null, 'https://youthforest.iksan.go.kr/index.iksan?menuCd=DOM_000000102007000000', 'https://youthforest.iksan.go.kr', null, null, '익산청년시청 ''전입 청년 부동산 중개보수비 및 이사비 지원사업'' 안내 원문으로 확인(2026-08-23). 2025-01-01 이후 익산시로 전입신고를 완료한 18~39세 1인 가구 청년, 가구 기준 중위소득 150% 이하, 외국인·재외국민 제외. 이사비(차량대여비·운반비·포장비 등, 청소비 제외) 30만원 한도 + 중개보수 20만원 한도 내 실비, 생애 1회. 접수는 2025-10-13부터 예산 소진 시까지 상시모집, 익산청년시청 온라인 신청, 문의 063-859-5745. applicationStart 에는 접수 시작일이 아니라 전입 기준일(2025-01-01)이 들어가 있었으므로 실제 접수 시작일로 바로잡았다. ⚠️ 다음 조건은 코드에서 판정하지 않는다: (1) ''2025-01-01 이후 익산시 전입'' — 전입일 입력 항목이 없음, (2) ''1인 가구'' 요건. 이 항목은 나이(18~39세)만 판정한다. ⚠️ 예산 소진 시 마감이라 상시모집이어도 실제 접수 가능 여부는 앱에서 알 수 없다.', 'apps/web/data 에서 이관 (2026-11-02)');
insert into public.data_policies (id, status, sort_order, name, agency, region_scope, effective_year, application_start, application_end, benefit_type, benefit_summary, monthly_cap, max_months, lump_sum_cap, lump_sum_basis, required_inputs, exclusive_group, discovery_age_min, discovery_age_max, discovery_regions, discovery_statuses, discovery_income_bracket_min, discovery_income_bracket_max, discovery_housing_types, source_url, apply_url, youth_policy_no, gov24_service_id, notes, edit_note)
values ('youth-housing-benefit-split-payment', 'published', 50, '청년 주거급여 분리지급', '국토교통부·보건복지부', '전국', 2026, '2026-01-01', null, 'rent_capped_monthly', '부모 가구와 다른 시·군·구에 거주하는 미혼 청년에게, 지역 급지별 기준임대료 한도 내 실제 월세만큼 매월 지급 (익산시는 4급지 — 1인 가구 월 최대 21만 2천원)', 212000, null, null, null, '{"birthDate","livesApartFromParents","householdSize","originHouseholdMonthlyIncome"}', '{"youth-rent-cash-support"}', 19, 29, '{"전국"}', '{"대학생","재직","구직"}', null, null, null, 'https://www.myhome.go.kr/hws/portal/cont/selectHousingBenefitView.do', 'https://www.bokjiro.go.kr', '20250617005400110952', null, '마이홈 ''주거급여 소개 및 선정기준''(2026년도 적용기준)과 복지로 ''청년 주거급여 분리지급 신청 안내'' 원문으로 확인(2026-08-23). 선정기준은 소득인정액 기준 중위소득 48% 이하(2026년 1인 가구 월 1,230,834원), 대상은 만 19세 이상 30세 미만 미혼 청년, 청년 명의 임대차계약 + 전입신고 필수, 기준임대료 상한 내 실제 임차료를 매월 20일 청년 명의 계좌로 별도 지급. monthlyCap 을 170,000원(추정)에서 212,000원으로 고쳤다 — 2026년 기준임대료 4급지(그 외 지역, 익산 포함) 1인 가구 값이다(급지별 1인: 1급지 369,000 / 2급지 300,000 / 3급지 247,000 / 4급지 212,000). ⚠️ 복지로 안내 페이지에는 소득기준이 ''중위소득 45% 이하''로 적혀 있는데 이는 2021년 시행 당시 값이다. 2026년 기준은 마이홈 표의 48% 다. ⚠️ 다음 조건은 코드에서 판정하지 않는다: (1) 미혼 여부 — 입력 항목 없음, (2) 부모 가구가 이미 주거급여 수급가구여야 한다는 요건 — 지금은 ''원가구 소득 48% 이하''로 근사하지만 실제로는 부모가 수급자로 선정되어 있어야 한다, (3) 거주지 요건은 ''부모와 주민등록상 시·군을 달리할 것''(동일 시·군도 보장기관 인정 시 예외)인데 ''부모와 별도 거주''로 근사 처리한다, (4) 부모 가구 주거유형이 사용대차·공동생활가정이면 신청 불가. ⚠️ discovery.incomeBracketMax 를 null 로 남긴 이유: 본인 소득이 아니라 부모를 포함한 원가구 소득인정액으로 심사한다. 1층 질문은 본인 월소득 구간만 묻기 때문에 원가구 가구원 수를 모르는 상태로는 소득으로 탈락시킬 수 없다(예: 본인 250만원이라도 원가구가 6인이면 48% 기준 안에 들어온다). 원가구 소득 기준을 본인 가구원 수 테이블로 계산하는 2층 코드 관례도 부정확할 수 있어 함께 검수할 것.', 'apps/web/data 에서 이관 (2026-11-02)');
insert into public.data_policies (id, status, sort_order, name, agency, region_scope, effective_year, application_start, application_end, benefit_type, benefit_summary, monthly_cap, max_months, lump_sum_cap, lump_sum_basis, required_inputs, exclusive_group, discovery_age_min, discovery_age_max, discovery_regions, discovery_statuses, discovery_income_bracket_min, discovery_income_bracket_max, discovery_housing_types, source_url, apply_url, youth_policy_no, gov24_service_id, notes, edit_note)
values ('jeonse-return-guarantee-fee-subsidy', 'published', 60, '전세보증금반환보증 보증료 지원', '국토교통부', '전국', 2026, '2026-01-01', null, 'lump_sum', '이미 낸 전세보증금반환보증(HUG·HF·SGI) 보증료를 최대 40만원까지 1회 지원 (2025-03-30 이전 가입건은 최대 30만원)', null, null, 400000, 'notCalculable', '{"birthDate","hasNoHouse","isContractHolder"}', '{}', null, null, '{"전국"}', '{"대학생","재직","구직"}', null, null, '{"전세"}', 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/161300000103', 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/161300000103', '20260527005400113223', '161300000103', '정부24 ''전세보증금반환보증 보증료 지원'' 안내 원문과 온통청년 등록(plcyNo 20260527005400113223, 2026-05-27 갱신)을 대조해 확인했다(2026-08-31). 대상은 신청일 기준 유효한 전세보증금반환보증(HUG·HF·SGI)에 가입한 임차보증금 3억원 이하 무주택 임차인, 연소득 기준은 청년 5천만원·청년외 6천만원·신혼부부 7.5천만원 이하. 이미 낸 보증료를 최대 40만원 한도로 지원하며 청년외는 납부액의 90%까지. 상시신청이되 지자체별 예산 소진 시 조기 마감. 시·군·구청·주민센터 방문 또는 온라인 접수. ⚠️ discovery.ageMin/ageMax 를 null(나이 제한 없음)로 뒀다 — 정부24 안내에 연령 요건이 없고 온통청년 등록도 sprtTrgtAgeLmtYn=''Y''(나이 제한 없음)다. ''청년''은 자격 요건이 아니라 소득 상한을 가르는 구분이라, 만 19~34세로 적으면 없는 제한을 만들어 대상자를 탈락시킨다. ⚠️ discovery.incomeBracketMax 를 null 로 뒀다 — 기준이 연소득 5천만원(월 약 417만원)이라 1층의 월 소득 구간(최대 ''250만원 초과'')으로는 상한을 가를 수 없다. 250만원 초과 구간에 5천만원 이하인 사람과 넘는 사람이 함께 들어온다. ⚠️ applicationStart 는 ''상시신청''을 데이터 모델에 담기 위해 2026-01-01 로 뒀다. 실제 접수 시작일이 아니며, 지자체 예산 소진 시 조기 마감되는 현황은 앱에서 알 수 없다. ⚠️ 다음 조건은 코드에서 판정하지 않는다: (1) 보증 가입 여부 — 이미 가입해 보증료를 낸 사람만 대상인데 입력 항목이 없다, (2) 보증금 3억원 이하, (3) 연소득 기준. ⚠️ lumpSumBasis 가 notCalculable 이다 — 2층 계약 화면은 보증료를 입력받지 않아 개인 예상액을 계산하지 않는다(공고 상한만 보여준다).', 'apps/web/data 에서 이관 (2026-11-02)');

-- ── 대출·보증 상품 ──
insert into public.data_loan_products (id, status, sort_order, name, agency, region_scope, effective_year, product_type, summary, source_url, apply_url, notes, edit_note)
values ('youth-btm-jeonse-loan', 'published', 10, '청년전용 버팀목 전세자금대출', '국토교통부·주택도시보증공사(HUG)', '전국', 2026, 'loan_interest_subsidy', '만 19~34세 무주택 세대주(예비세대주)에게 최저 약 2.0%대 저리로 전세보증금의 최대 80%(최대 2억원)까지 대출. 지방 거주 시 0.2%p 추가 금리 인하.', 'https://www.myhome.go.kr/hws/portal/cont/selectYouthPolicyYouthOnlyCrutchLoanView.do', 'https://www.myhome.go.kr', '미검증 초안(팀 교차검수 필요). 이자 절감액은 계산하지 않음(대출 실행 시점 금리·개인 신용도에 따라 달라짐) — 정확한 한도·금리는 주택도시기금 홈페이지 또는 콜센터(1566-9009)에서 확인. 연세 계약에는 적용되지 않을 수 있음(전세 계약 대상 상품).', 'apps/web/data 에서 이관 (2026-11-02)');
insert into public.data_loan_products (id, status, sort_order, name, agency, region_scope, effective_year, product_type, summary, source_url, apply_url, notes, edit_note)
values ('jeonse-return-guarantee-fee-subsidy', 'published', 20, '전세보증금반환보증 보증료 지원', '국토교통부', '전국', 2026, 'guarantee_fee_subsidy', '전세보증금 3억원 이하, 청년(연소득 5천만원 이하) 무주택 임차인이 가입한 전세보증금반환보증의 보증료를 최대 40만원까지 지원(기 납부한 보증료 전액, 2025-03-31 이후 가입 기준).', 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/161300000103', 'https://www.bokjiro.go.kr', '미검증 초안(팀 교차검수 필요). 이 앱은 현재 연세·월세 계약만 다루고 전세 계약(보증금 전액형)은 별도 입력 항목이 없어 자격 여부를 자동 판정하지 않음 — 전세 계약자에게만 참고용으로 안내. 신청은 주민센터·정부24·안심전세포털에서 가능.', 'apps/web/data 에서 이관 (2026-11-02)');
insert into public.data_loan_products (id, status, sort_order, name, agency, region_scope, effective_year, product_type, summary, source_url, apply_url, notes, edit_note)
values ('iksan-youth-home-purchase-loan-interest', 'published', 30, '신혼부부·청년 주택구입 대출이자 지원사업', '익산시', '전북특별자치도 익산시', 2026, 'loan_interest_subsidy', '익산시에 주소를 두고 2024-07-01 이후 주택을 구입한 19~39세 청년의 주택구입 대출잔액 3.0% 이내 이자를 소득기준별로 차등 지원. 지원기간 최대 5년(기본 3년, 자녀 수 증가 시 최대 5년).', 'https://youthforest.iksan.go.kr/board/view.iksan?boardId=BBS_0000015&menuCd=DOM_000000105002001000&paging=ok&startPage=1&dataSid=45005', 'https://youthforest.iksan.go.kr', '미검증 초안(팀 교차검수 필요). 익산청년시청 ''2026년 신혼부부 청년 주택구입 대출이자 지원사업'' 게시글 원문으로 확인(게시일 2026-02-09, 조회 2026-09-02). ⚠️ 신청기간은 원문 기준 ''2026-03-03 ~ 예산 소진 시까지''다 — 온통청년 API 등록값(plcyNo 20260325005400212264 의 aplyYmd, 2026-07-01~12-31)은 원문과 다르다. API 의 bizPrdBgngYmd(2026-03-03)는 원문과 일치하는데 aplyYmd 만 어긋나 있다 — aplyYmd 를 신뢰하지 않는다. ⚠️ 다음은 첨부 공고문(hwp, ''(공고)2026년신혼부부청년주택구입대출이자지원사업.hwp'')에만 있어 이 앱은 확인하지 못했다: 소득기준별 차등 지원 비율 구간표, 재산 기준 유무, 무주택 요건과의 정합성(''주택구입''을 전제로 하는 사업이라 ''무주택자만 대상''인지부터 애매하다), 지정 대출 상품·취급은행, 선착순 여부와 모집 규모(API 는 선착순 1,300명이라 하나 원문 게시글엔 언급이 없다).', 'apps/web/data 에서 이관 (2026-11-02)');
insert into public.data_loan_products (id, status, sort_order, name, agency, region_scope, effective_year, product_type, summary, source_url, apply_url, notes, edit_note)
values ('gunsan-newlywed-housing-loan-interest', 'published', 40, '신혼부부 주거자금 대출이자 지원사업', '군산시', '전북특별자치도 군산시', 2026, 'loan_interest_subsidy', '군산시 거주(혼인신고 7년 이내, 부부 모두 군산시 주민등록, 기준 중위소득 180% 이하) 신혼부부의 주택 구입 또는 전세 대출잔액 금리 2% 이내 이자 지원. 연 최대 300만원(월 25만원), 최대 3년(자녀 수에 따라 4~5년)까지 반기별(8월·12월) 지급.', 'https://www.gunsan.go.kr/main/m140/view/9831204', 'https://www.gunsan.go.kr', '미검증 초안(팀 교차검수 필요). 군산시청 주택행정과 ''2026년 군산시 신혼부부 주거자금 대출이자 지원사업 안내'' 원문으로 확인(작성일 2026-06-15, 조회 2026-09-02). ⚠️ 신청기간은 2026-07-01~07-20(접수기한 연장 포함)으로 이미 종료됐다 — 오늘(2026-09-02) 기준 신청 불가하고, 다음 회차 일정은 확인하지 못했다. ⚠️ 온통청년 plcyNo 20250710005400211162 는 이 정책의 2025년 이전 버전(''신혼부부 주택 전세자금 대출이자 지원사업'')으로, 이름·대상·금액이 전부 다르게 바뀌었다(혼인 5년→7년 이내, 전세만→주택구입 1주택 또는 전세 무주택, 연 200만원→300만원, 부부합산소득 8천만원 이하→기준 중위소득 180% 이하) — 그 번호를 이 정책과 연결하면 안 된다. 2026년 버전에 대응하는 온통청년 등록은 찾지 못했다. 대상주택(매입가액 5억원 또는 전세보증금 3억원 이하, 전용 85㎡ 이하)·본인부담금리 하한(연 1.0%)은 원문에서 확인했으나 실제 대출잔액·적용금리는 개인별로 달라 이 앱은 이자 절감액을 계산하지 않는다.', 'apps/web/data 에서 이관 (2026-11-02)');

